import * as THREE from 'three';

/**
 * Face definitions for a standard casino die.
 *
 * Opposite faces sum to 7:
 *   +y = 1 opposite -y = 6
 *   +z = 2 opposite -z = 5
 *   +x = 3 opposite -x = 4
 *
 * For each face, `n` is the outward normal and `u`/`v` span the face plane,
 * forming a right-handed local frame (u × v = n).
 */
export const FACES = [
  { value: 1, n: new THREE.Vector3(0, 1, 0), u: new THREE.Vector3(1, 0, 0), v: new THREE.Vector3(0, 0, 1) },
  { value: 6, n: new THREE.Vector3(0, -1, 0), u: new THREE.Vector3(1, 0, 0), v: new THREE.Vector3(0, 0, 1) },
  { value: 3, n: new THREE.Vector3(1, 0, 0), u: new THREE.Vector3(0, 0, -1), v: new THREE.Vector3(0, 1, 0) },
  { value: 4, n: new THREE.Vector3(-1, 0, 0), u: new THREE.Vector3(0, 0, 1), v: new THREE.Vector3(0, 1, 0) },
  { value: 2, n: new THREE.Vector3(0, 0, 1), u: new THREE.Vector3(1, 0, 0), v: new THREE.Vector3(0, 1, 0) },
  { value: 5, n: new THREE.Vector3(0, 0, -1), u: new THREE.Vector3(-1, 0, 0), v: new THREE.Vector3(0, 1, 0) },
];

/**
 * Standard pip grids in face-local (u, v) coordinates.
 * Coordinates are in units of the pip spacing `d` (see buildDie).
 *   0 = center, -1/+1 = the two symmetric offsets toward each edge pair.
 */
const PIP_GRIDS = {
  1: [[0, 0]],
  2: [[-1, -1], [1, 1]],
  3: [[-1, -1], [0, 0], [1, 1]],
  4: [[-1, -1], [1, -1], [-1, 1], [1, 1]],
  5: [[-1, -1], [1, -1], [0, 0], [-1, 1], [1, 1]],
  6: [[-1, -1], [-1, 0], [-1, 1], [1, -1], [1, 0], [1, 1]],
};

function findFace(normal) {
  return FACES.find(
    (f) => Math.abs(f.n.dot(normal)) > 0.999999 && f.n.x * normal.x + f.n.y * normal.y + f.n.z * normal.z > 0
  );
}

/**
 * Build a casino die: a BoxGeometry cube with small sphere pips flush on
 * every face using the standard layout (opposite faces sum to 7).
 *
 * Each pip is a child mesh of the returned die with
 * `userData.faceNormal` set to its face's outward normal.
 *
 * @param {{ size?: number, pipRadius?: number }} options
 * @returns {THREE.Mesh} the die (cube mesh with pip children)
 */
export function buildDie({ size = 2, pipRadius = 0.12 } = {}) {
  const half = size / 2;
  // Pip spacing: corner pips sit a quarter-size from the face center,
  // keeping every pip comfortably inside the face square minus pipRadius.
  const d = size * 0.25;

  const die = new THREE.Mesh(
    new THREE.BoxGeometry(size, size, size),
    new THREE.MeshStandardMaterial({ color: 0xf5f0e6, roughness: 0.35 })
  );

  const pipGeometry = new THREE.SphereGeometry(pipRadius, 24, 16);
  const pipMaterial = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.4 });

  for (const { value, n, u, v } of FACES) {
    for (const [a, b] of PIP_GRIDS[value]) {
      const pip = new THREE.Mesh(pipGeometry, pipMaterial);
      pip.position
        .copy(n)
        .multiplyScalar(half)
        .addScaledVector(u, a * d)
        .addScaledVector(v, b * d);
      pip.userData.faceNormal = n.clone();
      pip.userData.value = value;
      die.add(pip);
    }
  }

  return die;
}

/**
 * Return the world positions of all pips on the face whose outward normal
 * is `normal` (a THREE.Vector3 or array-like [x, y, z]).
 *
 * @param {THREE.Object3D} die - die built by buildDie()
 * @param {THREE.Vector3 | number[]} normal
 * @returns {THREE.Vector3[]}
 */
export function pipsOnFace(die, normal) {
  const n =
    normal instanceof THREE.Vector3
      ? normal
      : new THREE.Vector3(normal[0] ?? 0, normal[1] ?? 0, normal[2] ?? 0);

  const face = findFace(n);
  if (!face) return [];

  die.updateMatrixWorld(true);

  const positions = [];
  const tmp = new THREE.Vector3();
  for (const child of die.children) {
    if (!child.userData || !child.userData.faceNormal) continue;
    if (!child.userData.faceNormal.equals(face.n)) continue;
    positions.push(child.getWorldPosition(tmp.clone()));
  }
  return positions;
}

