import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildDie, pipsOnFace, FACES } from '../src/dice.js';

const SIZE = 2;
const PIP_RADIUS = 0.12;
const HALF = SIZE / 2;
const EPS = 1e-6;

const die = buildDie({ size: SIZE, pipRadius: PIP_RADIUS });

function countPips(dieObj, normal) {
  const n = new THREE.Vector3(...normal);
  return dieObj.children.filter((c) => c.userData?.faceNormal?.equals(n)).length;
}

describe('buildDie', () => {
  it('has total pip meshes equal to 21', () => {
    const pipMeshes = die.children.filter((c) => c.userData?.faceNormal);
    expect(pipMeshes.length).toBe(21);
  });

  it('has pip counts per face of 1, 2, 3, 4, 5, 6', () => {
    for (const { value, n } of FACES) {
      expect(countPips(die, [n.x, n.y, n.z]), `face ${value}`).toBe(value);
    }
  });

  it('has opposite faces summing to 7', () => {
    const axes = [
      [[0, 1, 0], [0, -1, 0]], // 1 vs 6
      [[0, 0, 1], [0, 0, -1]], // 2 vs 5
      [[1, 0, 0], [-1, 0, 0]], // 3 vs 4
    ];
    for (const [a, b] of axes) {
      const na = new THREE.Vector3(...a);
      const nb = new THREE.Vector3(...b);
      const fa = FACES.find((f) => f.n.equals(na));
      const fb = FACES.find((f) => f.n.equals(nb));
      expect(fa.value + fb.value).toBe(7);
      expect(countPips(die, a) + countPips(die, b)).toBe(7);
    }
  });

  it('lies with every pip center on its face plane within 1e-6', () => {
    for (const { value, n } of FACES) {
      const pips = pipsOnFace(die, n.clone());
      expect(pips.length).toBe(value);
      for (const p of pips) {
        expect(Math.abs(p.dot(n) - HALF)).toBeLessThanOrEqual(EPS);
      }
    }
  });

  it('keeps pips within the face square minus pipRadius', () => {
    const limit = HALF - PIP_RADIUS;
    for (const { n, u, v } of FACES) {
      const pips = pipsOnFace(die, n.clone());
      for (const p of pips) {
        const pu = p.dot(u);
        const pv = p.dot(v);
        expect(Math.abs(pu)).toBeLessThanOrEqual(limit + EPS);
        expect(Math.abs(pv)).toBeLessThanOrEqual(limit + EPS);
      }
    }
  });

  it('places exactly one pip at the +y face center', () => {
    const pips = pipsOnFace(die, new THREE.Vector3(0, 1, 0));
    expect(pips.length).toBe(1);
    const expected = new THREE.Vector3(0, HALF, 0);
    expect(pips[0].distanceTo(expected)).toBeLessThanOrEqual(EPS);
  });

  it('uses the standard pip grid shapes', () => {
    // 6 must be two columns of three: no pip at v=0 offset... check rows
    const six = FACES.find((f) => f.value === 6);
    const pips6 = pipsOnFace(die, six.n.clone());
    const us = new Set(pips6.map((p) => +p.dot(six.u).toFixed(6)));
    const vs = new Set(pips6.map((p) => +p.dot(six.v).toFixed(6)));
    expect(us.size).toBe(2); // two columns
    expect(vs.size).toBe(3); // three rows

    // 2 must be a diagonal: both offsets differ in u and v
    const two = FACES.find((f) => f.value === 2);
    const pips2 = pipsOnFace(die, two.n.clone());
    const du = Math.abs(pips2[0].dot(two.u) - pips2[1].dot(two.u));
    const dv = Math.abs(pips2[0].dot(two.v) - pips2[1].dot(two.v));
    expect(du).toBeGreaterThan(0);
    expect(dv).toBeGreaterThan(0);
  });
});

